        try c.assertionResolvedCallback(identifier, assertedTruthfully) {
            resolvedReverted = false;
        } catch {
            resolvedReverted = true;
        }

        bool disputedReverted;
        try c.assertionDisputedCallback(identifier) {
            disputedReverted = false;
        } catch {
            disputedReverted = true;
        }

        assert(priceReverted && resolvedReverted && disputedReverted && address(this).balance == beforeBal && address(c).balance == cBal);
    }

    receive() external payable {}
}

