        // We avoid abi.encodeWithSignature / address cast / interface alias for the call itself;
        // we still need to encode the selector, which is allowed as data.
        // The call is a plain top-level statement.
        bool reverted;
        (bool success, ) = address(c).call(abi.encodePacked(sel));
        reverted = !success;

        // Read the after-value.
        address afterAsserter = address(c.optimisticAsserter());

        assert(reverted && afterAsserter == beforeAsserter);
    }

    receive() external payable {}
}

