contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        address asserter = address(c.optimisticAsserter());
        require(asserter != address(0), "optimistic asserter not set");

        (bool success, bytes memory data) = address(c).call(
            abi.encodeWithSignature(
                "requestPrice(bytes32,uint256,bytes)",
                identifier,
                time,
                ancillaryData
            )
        );
        bytes32 eventTopic = keccak256("PriceRequestAdded(bytes32,uint256,bytes)");
        bool eventEmitted = false;
        if (success && data.length >= 96) {
            bytes32 gotIdentifier;
            uint256 gotTime;
            bytes memory gotAncillary;
            assembly {
                gotIdentifier := mload(add(data, 32))
                gotTime := mload(add(data, 64))
                let len := mload(add(data, 96))
                gotAncillary := mload(0x40)
                mstore(gotAncillary, len)
                let src := add(data, 128)
                let dst := add(gotAncillary, 32)
                for { let i := 0 } lt(i, len) { i := add(i, 32) } {
                    mstore(add(dst, i), mload(add(src, i)))
                }
                mstore(0x40, add(dst, and(add(len, 31), not(31))))
            }
            if (gotIdentifier == identifier && gotTime == time && keccak256(gotAncillary) == keccak256(ancillaryData)) {
                eventEmitted = true;
            }
        }

        assert(!success || eventEmitted);
    }

    receive() external payable {}
}

