            disputedReverted = false;
        } catch {
            disputedReverted = true;
        }

        try c.requestPrice(bytes32(0), 0, "") {
            priceReverted = false;
        } catch {
            priceReverted = true;
        }

        assert(resolvedReverted && disputedReverted && priceReverted);
    }

    receive() external payable {}
}

